public long countWays(int amount, int[] coins) {
    return count(coins, 0, amount);
}

private long count(int[] coins, int i, int rem) {
    if (rem == 0) return 1;
    if (rem < 0 || i == coins.length) return 0;
    return count(coins, i, rem - coins[i])   // use coin i again
         + count(coins, i + 1, rem);         // move past coin i
}

