public long countWays(int amount, int[] coins) {
    Long[][] memo = new Long[coins.length + 1][amount + 1];
    return count(coins, 0, amount, memo);
}

private long count(int[] coins, int i, int rem, Long[][] memo) {
    if (rem == 0) return 1;
    if (rem < 0 || i == coins.length) return 0;
    if (memo[i][rem] != null) return memo[i][rem];
    long ways = count(coins, i, rem - coins[i], memo)
              + count(coins, i + 1, rem, memo);
    return memo[i][rem] = ways;
}

code.python:
def count_ways(self, amount: int, coins: list[int]) -> int:
    n = len(coins)
    dp: list[list[int]] = [[0] * (amount + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = 1
    for i in range(1, n + 1):
        for x in range(1, amount + 1):
            dp[i][x] = dp[i - 1][x]
            if x >= coins[i - 1]:
                dp[i][x] += dp[i][x - coins[i - 1]]
    return dp[n][amount]

