public long countWays(int amount, int[] coins) {
    long[] dp = new long[amount + 1];
    dp[0] = 1;
    for (int coin : coins) {
        for (int x = coin; x <= amount; x++) {
            dp[x] += dp[x - coin];
        }
    }
    return dp[amount];
}

